import pathlib,json,hashlib,datetime,re,resource
resource.setrlimit(resource.RLIMIT_CPU,(120,120));resource.setrlimit(resource.RLIMIT_AS,(6*1024**3,6*1024**3))
r=pathlib.Path(__file__).resolve().parent;sha=lambda b:hashlib.sha256(b).hexdigest();raw=json.loads((r/'raw-records.json').read_text());reservation=json.loads((r/'reservation.json').read_text());ids=reservation['ids']
# Hand-authored dispositions: no automated novelty classification.
notes={
333576:('park_no_full_route','Conjecture 2 in v1; Conjecture 4.3 in v2/v3','Uniform reciprocal-width strip occupancy with an unbounded lower bound. Area averaging gives only a bounded scale; no multiscale argument proving divergence.','Target passages in all three versions; nearby spherical comparison. No full proof-body/citing-paper audit.'),
353676:('park_structural_infinite','Conjecture 5.2.7 and discussion after it; definitions in Section 1','All k>=3, infinite countable set-homogeneous hypergraphs with stable theory. The conditional expansion/classification argument needs Problem 5.2.5; homogeneous k=3 does not settle this.','Definition, stability conjecture and conditional argument read. Classification references not fully read.'),
367040:('exclude_source_exact_refutation','Question 1.5, Proposition 1.6, Lemma 3.1 and proof; Remark 3.2','The literal universal inequality is false already for a path base and adjacent internal vertices, by the printed path-walk argument. This is an exact source answer, not a new witness. The record also overstates the complete-graph positive theorem.','Source statement and ladder proof with S5 comparison read; Figures 1–2 text examined but not visually rendered.'),
335653:('park_no_uniform_stable_cover','Conjectures 2–3 and concluding bounded-stability paragraph','The complete-multidigraph theorem does not establish the stable-set domination assertion for arbitrary multidigraphs. A bound depending on stability number is not a bound depending only on k.','Target, definitions and bounded-stability mechanism read; cited kernel proofs not audited.'),
381125:('exclude_literal_classical_bridge_and_public_attempt','Definition 25, Theorem 26, Lemma 28, Conjecture 29','Literal record omits primitivity and follows from classical polynomial planar straight-line grid embedding. Stronger intended primitive question has a dated public CRT/5-degeneracy proof attempt. See ORDINARY_ATTEMPTS.md for the exact bridge and prior argument.','Source definitions and construction ending, polynomial-size discussion; full public ProbXiv argument read. Journal body 403; public attempt not independently certified.'),
374507:('park_ambient_structure_gap','Definition 4.1; Theorem 1.2; Proposition 11.1 and Conjecture 11.5','Need positive-density cubic visibility patch and strict ambient blocker bound for every permitted point set. A rich-line core does not give that algebraic structure.','Visibility patch definition, container theorem and final conjecture read; not a full audit of the long curve proof or its figures.'),
381928:('park_four_infinite_construction_families','Conjecture 1(i)–(iv), Remark 19, Sections 5.1–5.2','All four cyclic/2-split 6-/9-cycle existence families must be settled. Source prints small cyclic systems through v=30; short exceptional orbits repair naive divisibility objections. No all-size cyclic recursion.','Tight-cycle definition, four clauses, orbit remark and printed base-cycle lists read. Full appendices and figures not visually audited.'),
369109:('park_loops_require_new_hardness_reduction','Theorem 1, cover conventions, Conjecture 21','Semi-edge-only hardness does not include every loop completion of every tree. Loop incidences and semi-edges differ in local cover constraints; no uniform gadget reduction or easy target proving a substantive negation.','Main theorem and final exact conjecture, introductory conventions read; all reduction gadgets/proofs not audited.'),
370439:('park_sustained_no_full_mechanism','Definition 1.5; Theorem 1.10 proof; Conjecture 3.1; Theorem 3.3 and Proposition 3.4','Three ordinary approaches attempted: common-copy synchronization, independent fibre palettes, and printed local obstruction. Precise failures in ORDINARY_ATTEMPTS.md. No full extension theorem or explicit bad instance.','All three primary versions target passages; latest adjacent proof bodies read. Older distance-3 theorem statements and initial modification mechanism read, not full six-version proof audit. Journal 403.'),
337975:('park_sustained_orientation_compatibility_gap','Conjecture 6; Lemmas 3–5; Section 4.3 and concluding discussion','Need one cubic 3-connected bipartite graph and orientation making every perfect matching contain a directed cut, or a full theorem. Non-Hamiltonian seed, a-arc amplification and 1-factor decomposition routes each leave a precise gap.','All three versions target compared; gadget proof bodies and author copy target read. v3 PDF p6 Figure 3 visually inspected. Prior r87/r249 source-family exclusions reconciled.'),
325668:('park_classification_scope_unrecovered','Theorem 1.2 assumptions (A1)–(A4), Lemma 5.1, Section 5 discussion','The full projective-equivalence classification of eligible regular spreads is unpaid. Incidence eligibility is not equivalence classification. Exact database question wording not located in fetched v1.','Primary background assumptions and final spread criterion proof/discussion read. No full classification-body audit; source-fidelity uncertainty retained.'),
372550:('park_necessity_classification_gap','Scatteredness definition (2), Theorem 1.1, Conjecture 6.3','Need necessary and sufficient conditions over all intended parameters. Norm/P_s sufficient conditions and partial equality tests do not establish necessity. Missing theorem label in raw record recovered; h=0 and omitted gcd conventions cannot be used as discovery.','All four versions conjecture passages; latest definitions and sufficient theorem read. Full theorem proof, MRD equivalence proofs and all cited constructions not audited.'),
360294:('exclude_vacuous_domain_counterexample_intended_question_parked','Lemmas 4–5 and Conjecture 4','Exact literal negation: r=3,n=5,m=11, antecedent empty, consequent refuted by K5^3 plus {0,1,5}. Complete ordinary proof in ORDINARY_ATTEMPTS.md. Excluded domain correction/classical construction; intended nonempty-class implication unresolved here.','Definitions, contraction proofs, concluding conjectures and r=3 source range read. No global m(r) lower-bound proof or comprehensive later-paper audit.'),
335182:('park_rainbow_almost_spanning_factor','Problem 3.6; Conjecture 3.8; Proposition 3.9','A rainbow 2-factor on 2n vertices cannot use only 2n-1 colors, leaving the 2n-1 alternative. This does not refute the disjunction. No full rainbow cycle-union mechanism; do not exploit tiny n endpoints.','Conjecture, surrounding Latin-square bridge and earlier rainbow-path introduction read. No complete citing-proof audit.'),
336404:('park_prescribed_outer_cycles_gap','Conjecture 14 in v1; Conjecture 3.1, Observation 3.2 in v2','A cover must contain every outer cycle for the fixed Hist. Source already has at-most-three-outer-cycle cases and a deletion/colorability criterion. No all-outer-cycles lemma.','Hist/snark definitions and both versions target; nearby sufficient criterion read. Dot-product construction catalogue not exhaustively audited.'),
343137:('park_general_profinite_word_law','Conjecture 2 in v1; Conjecture 1.6 in v2','All words and fewer-than-continuum word values, not just countably many or special words. No open law subgroup proof. The additional 1306.5970 reference retrieved a small-profinite-rings paper; do not treat this as confirmation of identical word conjecture.','Both primary versions exact target and adjacent conditional results; companion introduction checked. Complete cardinal/topological argument and modern citing bodies not audited.'),
350737:('park_full_orders_unpaid_public_existential_resolution','Conjecture 4.9; arXiv:2609.20237 Corollary 1.2','Current public Corollary 1.2 already gives 0=delta_chi<delta_hom<delta_poly=1/m<delta_lin=1/4 for every odd m>=5. This pays the all-distinct subpart, not every admissible order. No full multi-part route.','Both source versions target; new citing primary Theorem 1.1 and Corollary 1.2 plus their explanatory deduction read. Full proof dependencies not audited.'),
347216:('park_source_fidelity_and_equivariance_gap','Theorem 1.1; Sections 4–5; Question 5.12; Section 8','An arbitrary prescribed transitive group must descend through the new cover. Presentation existence does not imply this. Exact displayed equivariant refinement not located in the fetched sole version.','Presentation/cover definitions and nearby statements/final questions inspected. No located exact source passage or full proof review of the database assertion.'),
374916:('park_famous_full_partition_regular_question','Conjecture 1.1 in both versions; companion 2507.00515 Conjecture 1.1','Must obtain all four of x,y,x+y,xy in a common cell for arbitrary finite colorings of positive integers. Two colors, rationals, or a three-point pattern do not settle it.','Both primary versions target and nearby pattern theorem; latest companion introduction read. Other companion downloaded but only introductory theorem passages read; no full modern literature audit.'),
373058:('park_pairwise_distinguishability_gap','Conjecture 1.5 in both versions; Theorem 1.3 and Definition 1.7','Main theorem separates proper classes from all graphs; target compares every pair of distinct immersion-closed union-closed classes. No class-pair equivalence counterexample or general separator proof.','Both versions target and surrounding immersion/hom-count statements read. Oddomorphism proof bodies and relevant external closure theorems not fully audited.')}
receipts=[]
for p in sorted(r.glob('receipts-*.json')):receipts+=json.loads(p.read_text())
results={}
for i in ids:
 k=str(i);v=raw[k];rec=v['record'];status,loc,gap,depth=notes[i]
 ps=sorted((r/'sources').glob(k+'v*.txt'));provenance={a:b for a,b in v.items() if a!='record'};provenance.update(raw_file='evidence/'+k+'.raw.jsonl',statement_utf8_sha256=sha(rec['statement'].encode()))
 results[k]={'mathdb_id':i,'title':rec['title'],'literal_statement':rec['statement'],'full_parsed_record':rec,'provenance':provenance,'disposition':status,'source_locators':loc,'actual_read_depth':depth,'ordinary_attempts_and_remaining_gap':gap,'ordinary_attempts_file':'ORDINARY_ATTEMPTS.md','source_versions_fetched':[p.name for p in ps], 'primary_text_hashes':{p.name:sha(p.read_bytes()) for p in ps},'source_receipts':[x for x in receipts if x.get('file','').split('/')[-1].startswith(k)],'historical_check':{'file':'history-exact-lines.txt','scope':'Project-wide exact-ID and arXiv-source matches in prose/results; broad family file search also retained in historical-matches.txt. Search hits are not proof review. Historical source-family results described in ORDINARY_ATTEMPTS.md.','global_novelty_clearance':False},'qualification_limits':['No exhaustive citing-body, journal/corrections, figure or worldwide literature clearance.','Current registry screens are routing evidence only; no all-code proof review.','No Lean endpoint, independent review, manuscript or replay exists for this lane.'],'pi_execution_qualified':False,'candidate':False,'credit_awarded':False}
assert len(results)==20 and set(results)==set(map(str,ids))
(r/'results.json').write_text(json.dumps(results,indent=2,ensure_ascii=False)+'\n')
# Source inventory separates availability from actual reading.
inv=[]
for p in sorted((r/'sources').iterdir()):
 if p.is_file():inv.append({'path':str(p.relative_to(r)),'sha256':sha(p.read_bytes()),'bytes':p.stat().st_size,'reading_status':'Per-ID depth in results.json; fetched does not mean fully read'})
(r/'source-inventory.json').write_text(json.dumps({'retrieval_receipts':receipts,'files':inv,'limits':'All 34 PDFs corresponding to listed versions of the 20 main arXiv sources fetched. Targeted reading only, not all full manuscripts; supplementary versions also fetched but not all read.'},indent=2)+'\n')
expected=(r/'reservation.sha256').read_text().split()[0];actual=sha((r/'reservation.json').read_bytes());assert actual==expected
(r/'reservation-after.json').write_text(json.dumps({'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'expected':expected,'actual':actual,'matches_before':actual==json.loads((r/'reservation-before.json').read_text())['actual'],'pass':True,'exact_20_keys':True},indent=2)+'\n')
print('Wrote exact',len(results),'results; immutable reservation',actual)
